<?php
declare(strict_types=1);
namespace KMM\Core;
/** Schema 11: additive; preserves the exact v1-v10 table definitions. */
final class SeedEntitySchema {
    public static function statements():array {return [
        "CREATE TABLE IF NOT EXISTS seed_entity_states (seed_key VARCHAR(64) PRIMARY KEY,record_type VARCHAR(40) NOT NULL,record_id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,company_id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,base_json LONGTEXT NOT NULL,seed_version VARCHAR(50) NOT NULL,source_document VARCHAR(2000) NOT NULL,source_checked_on DATE NOT NULL,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uniq_seed_entity_record(record_type,record_id),INDEX idx_entity_company(company_id),CONSTRAINT fk_seed_entity_company FOREIGN KEY(company_id) REFERENCES companies(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS seed_entity_overlays (seed_key VARCHAR(64) NOT NULL,field_key VARCHAR(64) NOT NULL,value_json LONGTEXT NOT NULL,author_id BIGINT UNSIGNED NULL,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(seed_key,field_key),CONSTRAINT fk_entity_overlay_state FOREIGN KEY(seed_key) REFERENCES seed_entity_states(seed_key),CONSTRAINT fk_entity_overlay_actor FOREIGN KEY(author_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
        "CREATE TABLE IF NOT EXISTS seed_entity_conflicts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,batch_id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,seed_key VARCHAR(64) NOT NULL,record_type VARCHAR(40) NOT NULL,record_id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,company_id CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,field_key VARCHAR(64) NOT NULL,old_json LONGTEXT NOT NULL,incoming_json LONGTEXT NOT NULL,user_json LONGTEXT NOT NULL,effective_json LONGTEXT NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'pending',revision INT UNSIGNED NOT NULL DEFAULT 1,decision VARCHAR(24) NULL,resolver_id BIGINT UNSIGNED NULL,resolved_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uniq_entity_conflict(batch_id,seed_key,field_key),INDEX idx_entity_conflict_pending(status,id),CONSTRAINT fk_entity_conflict_batch FOREIGN KEY(batch_id) REFERENCES seed_update_batches(id),CONSTRAINT fk_entity_conflict_state FOREIGN KEY(seed_key) REFERENCES seed_entity_states(seed_key),CONSTRAINT fk_entity_conflict_company FOREIGN KEY(company_id) REFERENCES companies(id),CONSTRAINT fk_entity_conflict_resolver FOREIGN KEY(resolver_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci"
    ];}
}
